from pathlib import Path
import json,hashlib,statistics,difflib
r=Path(__file__).parent
read=lambda n:json.loads((r/n/'result.json').read_text())
canonical='cae68ae4879051f55b6b7dabc787ab4c5627557f0117d3d8cc32bacbee6f0466'
rows=[]
for p in sorted(r.glob('*/result.json'),key=lambda p:p.stat().st_mtime):
 v=json.loads(p.read_text());label=v['label'];v['correctness']='not completed'
 if v['rc']==0:
  expected=canonical if v['update'] else v['initial_sha']
  if label.startswith('early-') and v['update']:expected=read('early-base-update')['final_sha']
  if label.startswith('small-live-'):expected=read('small-live-base')['final_sha']
  if label.startswith('reset-'):expected=read('reset-base')['final_sha']
  if label.startswith('sync-'):expected=read('sync-base')['final_sha']
  if label.startswith('mature-live-') and v['update']:expected=read('mature-live-base-update')['final_sha']
  v['correctness']='exact checkpoint' if v['final_sha']==expected else 'different checkpoint'
 if v.get('profile') or 'phases' in label:v['timing_note']='instrumented; excluded from speed claim'
 rows.append(v)
(r/'results.json').write_text(json.dumps(rows,indent=2))
text=['# All training optimization screens','', '| Case | SPS | GPU MiB | Weight updates | Checkpoint |','|---|---:|---:|---|---|']
for v in rows:text.append(f"| {v['label']} | {v.get('sps',0):,.0f} | {v.get('used_mib',0):,.0f} | {v['update']} | {v['correctness']}{'; diagnostic timing' if v.get('timing_note') else ''} |")
text+=['','Replay cases verify three observation hashes. Frozen cases verify unchanged policy weights; that alone does not prove identical gradients. Full state and live trajectory comparisons are in final-state-proof.json. Failed Nsight finalization is a profiler issue, not a training crash.','']
(r/'RESULTS.md').write_text('\n'.join(text))
base_labels=['baseline-frozen-repeat','baseline-final1','baseline-final2'];candidate_labels=['memory-repeat1','memory-repeat2','retained-final1']
base_labels=[n for n in base_labels if (r/n/'result.json').exists()];candidate_labels=[n for n in candidate_labels if (r/n/'result.json').exists()]
base_sps=262144/statistics.mean(read(n)['seconds'] for n in base_labels);new_sps=262144/statistics.mean(read(n)['seconds'] for n in candidate_labels)
best={'name':'retained','binary':str(r/'retained/puffer_retained'),'flags':['PUF_MUON_BATCH_NORM','PUF_MINGRU_NOCOPY','PUF_SKIP_UNUSED_LOGPS','PUF_MUON_OUTPLACE','PUF_PPO_ZERO','PUF_BYTE_OBS','PUF_REUSE_ROLLOUT'],'control_cases':base_labels,'candidate_cases':candidate_labels,'control_sps':base_sps,'frozen_sps':new_sps,'gain_percent':100*(new_sps/base_sps-1),'validation':json.loads((r/'final-state-proof.json').read_text())}
(r/'best.json').write_text(json.dumps(best,indent=2))
s=['# Two-hour NetHack training optimization report','','18 September 2026, 10:19–12:19 UTC. Baseline already includes engine61, environment pool83, the cuBLAS workspace fix, strict reductions and the head sampler. These are incremental gains over that baseline, not over upstream PufferLib. Production sources are unchanged.','',f'## Main result: {100*(new_sps/base_sps-1):.1f}% more training throughput','', '| Workload | Baseline SPS | Retained SPS | Gain |','|---|---:|---:|---:|',f'| Mature recorded workload, three short repeats | {base_sps:,.0f} | {new_sps:,.0f} | {100*(new_sps/base_sps-1):.1f}% |']
for name,a,b in [('Mature games, live actions after saved prefix','mature-live-base','mature-live-retained'),('Early live training, 15.55M parameters','early-base-update','early-memory-update'),('Early live training, 1.98M parameters','small-live-base','small-live-retained')]:
 x,y=read(a),read(b);s.append(f"| {name} | {x['sps']:,.0f} | {y['sps']:,.0f} | {100*(y['sps']/x['sps']-1):.1f}% |")
if (r/'small-retained/result.json').exists():
 small_b=[n for n in ['small-baseline','small-base-repeat','small-base-repeat2'] if (r/n/'result.json').exists()]
 small_c=[n for n in ['small-retained','small-retained-repeat','small-retained-repeat2'] if (r/n/'result.json').exists()]
 xs=262144/statistics.mean(read(n)['seconds'] for n in small_b);ys=262144/statistics.mean(read(n)['seconds'] for n in small_c)
 s.append(f"| Mature recorded workload, 1.98M parameters (short repeats) | {xs:,.0f} | {ys:,.0f} | {100*(ys/xs-1):.1f}% |")
s+=['', 'GPU allocation in matched normal-update tests falls from 15,597 MiB (15.2 GiB) to 8,095 MiB (7.9 GiB), a 48.1% reduction. Frozen tests have an additional scratch allocation; compare like with like.','', '## Retained implementation changes','', '1. Batch independent per-matrix Muon normalization kernels while preserving each reduction tree and rounding.','2. Use separate C/D outputs in cuBLASLt for accumulating Newton–Schulz GEMMs, eliminating preliminary copies.','3. Remove redundant MinGRU state/input copies; preserve input lifetime through backward completion.','4. Skip unused action-head log-probability work and coalesce unused gradient zeroing. The PPO objective is unchanged.','5. Store raw byte observations without expanding the rollout buffers to BF16. The encoder reads the same byte values; learned activations remain BF16.','6. Reuse eight rollout graphs with one-step staging instead of capturing one per buffer, time step and async slot. This primarily saves memory.','', '## Correctness evidence','', '- Normal mature replay: all 15,552,136 FP32 master weights, FP32 optimizer momentum and BF16 updates are byte-identical after 1,808 updates.','- Live early training: the same checks pass at 15.55M and 1.98M parameters; observation hashes agree.','- Mature live actions: observation hashes agree after switching off action replay following the saved prefix.','- Main tests enable recurrent carry (`reset_every_horizon=0`); a separate live-updating reset-at-horizon pair also has identical checkpoints and observation hashes.','- Standalone normalization oracle covers five input patterns over 4,588,861 elements each. Byte-storage transpose oracle covers all 65,536 bit patterns.','- Synchronous training and reset-at-horizon are additional checkpoint/trajectory checks. These are finite deterministic checks, not a proof for every architecture, precision, CUDA version or GPU. Retained cuBLASLt plans and byte containers target the tested BF16 NetHack configuration.','', '## Benchmark protocol and limits','', 'One RTX4090, 512 environments, four rollout buffers, 24 environment-pool workers, horizon512, minibatch4096, replay ratio1.78021395 (113 updates/batch), four recurrent layers, hidden width1024. Six steady-state batches (epochs8–13) are timed in each 16-batch run. SPS counts policy/environment decisions, not NetHack keystrokes.','', 'The mature workload is initialized by replaying 12,288 decisions per environment. It represents established score-farming games, not a deep Castle-policy corpus. The main controlled replay benchmark continues recorded environment actions while executing real inference, sampling, forward, loss, backward and optimizer work. It is a compute benchmark, not a valid learning-quality evaluation. Frozen mode redirects parameter writes to scratch while preserving the mature policy. The supplementary mature-live test stops replay after the prefix; the policy then chooses its own actions, with zero initial recurrent memory and eight warmup batches before timing. Early live tests really update the policy. The small model is randomly initialized, not a trained mature small-policy checkpoint.','', '## Remaining bottleneck','', 'Measured GPU training-stream intervals per batch (concurrent rollout interference is included; these are not exclusive GPU utilization shares):','', '| Stage | Baseline ms | Retained ms |','|---|---:|---:|']
ph=json.loads((r/'final-phases.json').read_text())
for k,name in [('forward_ms','Forward and importance-cache work'),('loss_ms','Advantages and PPO loss'),('backward_ms','Backward'),('optimizer_ms','Muon optimizer and final cast')]:s.append(f"| {name} | {ph['baseline-phases'][k]:.1f} | {ph['retained-phases'][k]:.1f} |")
s+=['', 'Backward computation and optimizer matrix work dominate the remaining training-stream time. The smaller model is much more sensitive to mature rollout cost; its short-run SPS varies by several percent, so no mature-workload speedup is established for it. Smaller local kernel timings did not reliably improve end-to-end throughput, so the acceptance criterion was full-pipeline SPS.','', 'Nsight node tracing worked for the baseline but repeatedly stalled while finalizing optimized traces. Verified profiler PIDs were stopped; no training job was mistaken for a successful trace. The final stage timings use working GPU globaltimer instrumentation instead.','', '## Rejected or parked ideas','', 'Fused optimizer cast; direct bias atomics; stream priorities; cached embedding tables; fused entity pooling; sampled timing events; batched host uploads; sampler shared-memory caching; parallel Muon streams; compact normalization grids; identity-row indexing; grouped entity GEMMs; alternative scan load geometry and shared mask packing; fused final Muon writes; repeated-message reuse; WMMA entity MLPs; serialized/deferred backward GEMMs; shared bias reductions. They were flat or slower in full training. SM-target tuning also changed checkpoint bits. Alternate cuBLASLt heuristic ranks reached up to ~193k SPS but changed checkpoint bits and were not accepted. See RESULTS.md for individual screens and prepare_*.py for prototypes.','', '## Artifacts','', '- `minimal/` and `optimizations-only.patch`: stripped implementation, rebuilt and checked against the baseline checkpoint. `build_minimal.sh` rebuilds it. `retained/` adds validation instrumentation.','- `optimizations-only.patch`: implementation changes relative to the existing batch-sweep benchmark source. `retained.patch` also includes optional validation instrumentation; not a drop-in upstream PR. `build_retained.sh` rebuilds it and `reproduce.sh TAG` runs the controls and update proof on this box.','- `best.json`, `final-state-proof.json`, `final-phases.json`: machine-readable result and correctness evidence.','- `RESULTS.md`, `results.json`: all screens, including rejected ones.','- Each case directory contains exact command/environment, full log and checkpoint. The rollout-tail diagnostic assumes async mode and is not valid in the two synchronous correctness cases.','']
(r/'SUMMARY.md').write_text('\n'.join(s))
print('repeat SPS',base_sps,new_sps,'gain',best['gain_percent'])
